9	    /// Require the default clause in switch statements.
10	    ///
11	    /// Some code conventions require that all switch statements have a default clause. The thinking is that it’s better
12	    /// to always explicitly state what the default behavior should be so that it’s clear whether or not the developer
13	    /// forgot to include the default behavior by mistake.
14	    ///
15	    /// ## Examples
16	    ///
17	    /// ### Invalid
18	    ///
19	    /// ```js,expect_diagnostic
20	    /// switch (a) {
21	    ///     case 1:
22	    ///         /* code */
23	    ///         break;
24	    /// }
25	    /// ```
26	    ///
27	    /// ### Valid
28	    ///
29	    /// ```js
30	    /// switch (a) {
31	    ///     case 1:
32	    ///         /* code */
33	    ///         break;
34	    ///
35	    ///     default:
36	    ///         /* code */
37	    ///         break;
38	    /// }
39	    /// ```
40	    pub UseDefaultSwitchClause {
41	        version: "1.7.2",
42	        name: "useDefaultSwitchClause",
43	        language: "js",
44	        sources: &[RuleSource::Eslint("default-case")],
45	        recommended: false,
46	    }
47	}
