17	    /// Disallow unnecessary concatenation of string or template literals.
18	    ///
19	    /// This rule aims to flag the concatenation of 2 literals when they could be combined into a single literal. Literals can be strings or template literals.
20	    /// Concatenation of multiple strings is allowed when the strings are spread over multiple lines in order to prevent exceeding the maximum line width.
21	    ///
22	    /// ## Examples
23	    ///
24	    /// ### Invalid
25	    ///
26	    /// ```js,expect_diagnostic
27	    /// const a = "a" + "b";
28	    /// ```
29	    ///
30	    /// ```js,expect_diagnostic
31	    /// const a = "a" + "b" + "c";
32	    /// ```
33	    ///
34	    /// ```js,expect_diagnostic
35	    /// const a = (foo + "a") + ("b" + "c");
36	    /// ```
37	    ///
38	    /// ### Valid
39	    ///
40	    /// ```js
41	    /// const a = 1 + 1;
42	    /// ```
43	    ///
44	    /// ```js
45	    /// const a = 1 * '2';
46	    /// ```
47	    ///
48	    /// ```js
49	    /// const a = 1 - 2;
50	    /// ```
51	    ///
52	    /// ```js
53	    /// const a = foo + bar;
54	    /// ```
55	    ///
56	    /// ```js
57	    /// const a = 'foo' + bar;
58	    /// ```
59	    ///
60	    /// ```js
61	    /// const a = 'foo' +
62	    ///           'bar'
63	    /// ```
64	    pub NoUselessStringConcat {
65	        version: "next",
66	        name: "noUselessStringConcat",
67	        language: "js",
68	        sources: &[RuleSource::Eslint("no-useless-concat")],
69	        recommended: false,
70	        fix_kind: FixKind::Unsafe,
71	    }
72	}
