16	declare_rule! {
17	    /// Disallow the use of yoda expressions.
18	    ///
19	    /// A Yoda expression is a programming style where, given a binary operation, the "static" part of the binary operation is placed on the left-hand side.
20	    /// This rule **forbids** the use of Yoda expressions and enforces the placing of the "static" part of the binary operations on the right-hand side.
21	    ///
22	    /// ## Exceptions
23	    ///
24	    /// Range expressions like `0 < value && value < 1` or `value <= 0 || 1 < value` are allowed.
25	    ///
26	    /// ## Examples
27	    ///
28	    /// ### Invalid
29	    ///
30	    /// ```js,expect_diagnostic
31	    /// if ("red" == value) {}
32	    /// ```
33	    ///
34	    /// ```js,expect_diagnostic
35	    /// if (true === value) {}
36	    /// ```
37	    ///
38	    /// ```js,expect_diagnostic
39	    /// if (5 != value) {}
40	    /// ```
41	    ///
42	    /// ### Valid
43	    ///
44	    /// ```js
45	    /// if (value === "red") {}
46	    /// ```
47	    ///
48	    /// ```js
49	    /// if (value === value) {}
50	    /// ```
51	    ///
52	    /// ```js
53	    /// if (value != 5) {}
54	    /// ```
55	    ///
56	    /// ```js
57	    /// if (0 < value && value < 1) {}
58	    /// ```
59	    ///
60	    /// ## Resources
61	    /// - [Wikipedia definition](https://en.wikipedia.org/wiki/Yoda_conditions)
62	    ///
63	    pub NoYodaExpression {
64	        version: "next",
65	        name: "noYodaExpression",
66	        language: "js",
67	        sources: &[RuleSource::Eslint("yoda")],
68	        recommended: false,
69	        fix_kind: FixKind::Safe,
70	    }
71	}
